// core.js — no fs, no fetch, no Date.now(), no Math.random()
export function decideMonthlyCharge(sub, now) {
  const monthly = { free: 0, pro: 2900, team: 9900 }[sub.tier];
  if (!monthly) return { kind: 'no-charge' };
  const days = Math.max(0, (now - new Date(sub.startedAt)) / 86400000);
  return { kind: 'charge', amountCents: Math.round(monthly * days / 30) };
}
// shell.js — reads, decides, writes
const sub = await db.subscription(active.id);
const decision = decideMonthlyCharge(Object.freeze(sub), new Date());
if (decision.kind === 'charge') await stripe.charge(decision.amountCents);
